"""Small controls for all-memory algebra; no width or frontier census."""
import collections,datetime,hashlib,json,os,platform,resource,signal,subprocess,sys,tempfile,time
from pathlib import Path
resource.setrlimit(resource.RLIMIT_CPU,(120,120));resource.setrlimit(resource.RLIMIT_AS,(1024**3,1024**3));signal.alarm(180)
start=time.monotonic();stamp=datetime.datetime.now(datetime.timezone.utc).isoformat();root=Path('/home/ryan/rule30-lab');sha=lambda b:hashlib.sha256(b).hexdigest()
def T(x):return x^((x<<1)|(x<<2))
def G(x,g):return T(x)if g=='t'else T(x)^1 if g=='u'else T(2*x+1)>>1
def A(x):return T(x)>>2
def it(x,n):
 for _ in range(n):x=A(x)
 return x
for x,vals in {0:[0,1,3],1:[7,6,6],2:[14,15,13],3:[13,12,12]}.items():assert[G(x,g)for g in 'tup']==vals
sections=[]
for v in range(16):
 for s in range(4):
  x=A(4*v+s);y=G(v,'tupp'[s]);assert x==y;sections.append([v,s,x])
rot=[]
for y in range(64):
 x=0
 for j in range(6):
  if ((T(x)^y)>>j)&1:x|=1<<j
 assert T(x)%64==y
 z=G(x,'p')%64;assert z==4*(y>>2)+(y-1)%4;rot.append([y,x,z])
def pair(q,g,b,r):return[it(q,r)%(1<<b),'tupp'[it(G(q,g),r-1)%4]]
groups=[];count=0
for b,r in [(2,2),(4,3)]:
 for base in range(1<<b):
  for g in 'tup':
   tab=[0]*(3*(1<<b))
   for z in range(1<<(2*r)):
    q=base+(z<<b);v,h=pair(q,g,b,r);tab[3*v+'tup'.index(h)]+=1;count+=1
   assert tab==[a for _ in range(1<<b)for a in [1,1,2]]
   groups.append({'b':b,'r':r,'base':base,'generator':g,'joint_counts':tab})
bad=[pair(z<<4,'t',4,2)for z in range(16)];letter=[sum(h==g for _,h in bad)for g in 'tup'];assert letter==[16,0,0]
summary={'section_cases':64,'low_rotation_cases':64,'uniform_pairs':[[2,2],[4,3]],'uniform_groups':len(groups),'uniform_lifts':count,'all_uniform_groups_pass':True,'too_early_control':{'b':4,'r':2,'base':0,'generator':'t','letter_counts':letter,'uniform_prediction':[4,4,8]},'largest_modulus':1024,'new_frontiers':0,'new_solver_runs':0}
names=['proofs/informal/problem1_all_residue_memory_rigidity.md','proofs/informal/problem1_period_two_schedule_survivor.md','proofs/informal/problem1_fixed_block_potential_decision.md','results/problem1/20260906_fixed_block_potential_verification.json'];source=Path(__file__).read_text()
rec={'experiment_id':'problem1-all-residue-memory-controls-20260906','timestamp_utc':stamp,'git_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'question':'problem1','hypothesis':'Section/low-rotation identities and uniform-fiber condition pass small controls; omitting2r-2>=b fails.','backend':'packed-exact-small-identity-controls','parameters':{'sections_v':list(range(16)),'sections_s':[0,1,2,3],'rotation_y':list(range(64)),'uniform_pairs':[[2,2],[4,3]],'early_control':[4,2,0,'t'],'cpu_seconds_cap':120,'wall_seconds_cap':180,'memory_bytes_cap':1024**3},'hardware':{'cpu_count':os.cpu_count(),'machine':platform.machine()},'software':{'python':sys.version,'platform':platform.platform()},'runtime_seconds':time.monotonic()-start,'inputs':{n:sha((root/n).read_bytes())for n in names},'admission_note_snapshot':(root/names[0]).read_text(),'source_text':source,'result_hashes':{'source_sha256':sha(source.encode()),'summary_sha256':sha(json.dumps(summary,sort_keys=True).encode()),'reference_sha256':sha((root/'src/python/rule30_research_reference.py').read_bytes())},'result_summary':summary,'results':{'sections':sections,'rotations':rot,'uniform_groups':groups,'early_control_pairs':bad},'status':'finite-exhaustive','proof_scope':'Only the declared small identities and a16-lift counterexample; all-memory rigidity rests on a separate symbolic proof.','interpretation':'Controls pass; uniform averaging without its threshold is refuted. No all-memory conclusion is inferred from this finite table alone.','limitations':['Six preceding Muse attempts failed429; seventh proof review requested separately. Lead-local controls, no substitution.','No width/rank sweep, ordinary frontier, occurrence or new optimization.','No infinite forced continuation is assumed in pure scanner controls.']}
out=root/'results/problem1/20260906_all_memory_primary.json';fd,tmp=tempfile.mkstemp(dir=out.parent,prefix=out.name+'.')
with os.fdopen(fd,'w')as f:json.dump(rec,f,indent=2,sort_keys=True);f.write('\n');f.flush();os.fsync(f.fileno())
os.replace(tmp,out);print(json.dumps(summary))
